generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model Puzzle {
  date      String   @id
  word      String
  createdAt DateTime @default(now())
  guesses   Guess[]
}

model Guess {
  id         String   @id @default(cuid())
  puzzleDate String
  puzzle     Puzzle   @relation(fields: [puzzleDate], references: [date])
  player     String
  word       String
  result     Json
  correct    Boolean
  createdAt  DateTime @default(now())

  @@unique([puzzleDate, player, word])
}

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

export default prisma;

import express from 'express';
import router from './routes.js';

const app = express();
const PORT = process.env.PORT || 9090;

// Middleware
app.use(express.json());

// Routes
app.use('/', router);

// Centralized error handler — Express 5 auto-catches async rejections
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
  });
});

// Start server
app.listen(PORT, () => {
  console.log(`🟩 Wordle Battle API running on http://localhost:${PORT}`);
});

export default app;

import { readFileSync } from 'fs';

const { answers, extraGuesses } = JSON.parse(
  readFileSync(new URL('./words.json', import.meta.url), 'utf8'),
);

export const ANSWERS = answers;

// Superset of all valid words (answers + extra guesses)
const VALID_WORDS = new Set([...ANSWERS, ...extraGuesses]);

/** Pick a random answer word, avoiding any previously used words. */
export function getRandomAnswer(usedWords = []) {
  const used = new Set(usedWords);
  const available = ANSWERS.filter((w) => !used.has(w));
  const pool = available.length > 0 ? available : ANSWERS;
  return pool[Math.floor(Math.random() * pool.length)];
}

/** Check if a word is in the valid guess dictionary. */
export function isValidWord(word) {
  return VALID_WORDS.has(word.toLowerCase());
}

import { z } from 'zod';

// Zod validation middleware factory
// Usage: router.post('/route', validateBody(schema), handler)
export function validateBody(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(422).json({
        error: 'Validation failed',
        details: result.error.issues,
      });
    }
    req.body = result.data;
    next();
  };
}

// --- Schemas ---

export const GuessSchema = z.object({
  player: z.string()
    .min(1, { error: 'Player name is required' })
    .max(30, { error: 'Player name must be 30 characters or fewer' })
    .regex(/^[\w-]+$/, { error: 'Player name can only contain letters, numbers, underscores, and hyphens' }),
  word: z.string()
    .length(5, { error: 'Guess must be exactly 5 letters' })
    .regex(/^[a-zA-Z]+$/, { error: 'Guess must contain only letters' })
    .transform((w) => w.toLowerCase()),
});

import { Router } from 'express';
import { validateBody, GuessSchema } from './middleware/validate.js';
import { getPuzzleState } from './controllers/puzzle_controller.js';
import { submitGuess } from './controllers/guess_controller.js';

const router = Router();

// Welcome
router.get('/', (req, res) => {
  res.json({ message: 'Welcome to the Wordle Battle API! 🟩🟨⬜' });
});

// Puzzle state + leaderboard (use "today" or a date like "2026-02-18")
router.get('/puzzles/:date', getPuzzleState);

// Submit a guess
router.post('/puzzles/:date/guesses', validateBody(GuessSchema), submitGuess);

export default router;

/** Resolve ":date" param — "today" becomes "YYYY-MM-DD". */
export function resolveDate(param) {
  if (param === 'today') {
    return new Date().toISOString().slice(0, 10);
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(param)) {
    const err = new Error('Invalid date format. Use "today" or "YYYY-MM-DD".');
    err.status = 400;
    throw err;
  }
  return param;
}

/** Get or auto-create the puzzle for a given date. */
export async function getOrCreatePuzzle(date) {
  const existing = await prisma.puzzle.findUnique({ where: { date } });
  if (existing) return existing;

  const usedWords = (await prisma.puzzle.findMany({ select: { word: true } }))
    .map((p) => p.word);

  return prisma.puzzle.create({
    data: { date, word: getRandomAnswer(usedWords) },
  });
}

/**
 * GET /puzzles/:date
 * Puzzle state + leaderboard. Optional ?player= for personal stats.
 */
export async function getPuzzleState(req, res) {
  const date = resolveDate(req.params.date);

  await getOrCreatePuzzle(date);
  const guesses = await prisma.guess.findMany({
    where: { puzzleDate: date },
    orderBy: { createdAt: 'asc' },
  });

  // Build leaderboard: players who solved it, ranked by fewest guesses
  const playerStats = {};
  for (const guess of guesses) {
    if (!playerStats[guess.player]) {
      playerStats[guess.player] = { guesses: 0, solved: false };
    }
    playerStats[guess.player].guesses += 1;
    if (guess.correct) {
      playerStats[guess.player].solved = true;
    }
  }

  const leaderboard = Object.entries(playerStats)
    .filter(([, stats]) => stats.solved)
    .sort((a, b) => a[1].guesses - b[1].guesses)
    .map(([name, stats]) => ({ player: name, guesses: stats.guesses }));

  const { player } = req.query;

  const response = {
    date,
    totalPlayers: Object.keys(playerStats).length,
    leaderboard,
  };

  // If ?player= is specified, include their guess history and status
  if (player) {
    const pGuesses = guesses.filter((g) => g.player === player);
    const solved = pGuesses.some((g) => g.correct);
    response.playerGuesses = pGuesses.map((g) => ({
      word: g.word,
      result: g.result,
      correct: g.correct,
    }));
    response.playerStatus = solved ? 'solved' : pGuesses.length >= 6 ? 'lost' : 'playing';
  }

  return res.json(response);
}

const MAX_GUESSES = 6;

/**
 * Two-pass algorithm for Wordle-style letter feedback.
 * Pass 1: Mark exact matches ("correct"), null out matched positions.
 * Pass 2: For remaining letters, check if they exist elsewhere ("present" or "absent").
 */
export function checkGuess(guess, answer) {
  const result = Array(5).fill(null);
  const answerLetters = [...answer];
  const guessLetters = [...guess];

  // Pass 1 — greens (exact matches)
  for (let i = 0; i < 5; i++) {
    if (guessLetters[i] === answerLetters[i]) {
      result[i] = { letter: guessLetters[i], state: 'correct' };
      answerLetters[i] = null;
      guessLetters[i] = null;
    }
  }

  // Pass 2 — yellows and grays
  for (let i = 0; i < 5; i++) {
    if (guessLetters[i] === null) continue; // already matched

    const idx = answerLetters.indexOf(guessLetters[i]);
    if (idx !== -1) {
      result[i] = { letter: guessLetters[i], state: 'present' };
      answerLetters[idx] = null; // consume this answer letter
    } else {
      result[i] = { letter: guessLetters[i], state: 'absent' };
    }
  }

  return result;
}

/**
 * POST /puzzles/:date/guesses
 * Submit a guess for a puzzle. Auto-registers the player on first guess.
 */
export async function submitGuess(req, res) {
  const date = resolveDate(req.params.date);
  const { player, word } = req.body;

  // Get or create the puzzle for this date
  const puzzle = await getOrCreatePuzzle(date);

  // Validate the word is in our dictionary (before entering transaction)
  if (!isValidWord(word)) {
    return res.status(422).json({ error: `"${word}" is not a valid word` });
  }

  // Atomic transaction: read guesses → validate → write
  const guess = await prisma.$transaction(async (tx) => {
    const playerGuesses = await tx.guess.findMany({
      where: { puzzleDate: date, player },
      orderBy: { createdAt: 'asc' },
    });

    // Check if this player already solved it
    if (playerGuesses.some((g) => g.correct)) {
      const err = new Error('You already solved this puzzle!');
      err.status = 400;
      throw err;
    }

    // Check max guesses
    if (playerGuesses.length >= MAX_GUESSES) {
      const err = new Error('No guesses remaining (max 6)');
      err.status = 400;
      throw err;
    }

    // Check for duplicate guess
    if (playerGuesses.some((g) => g.word === word)) {
      const err = new Error(`You already guessed "${word}"`);
      err.status = 400;
      throw err;
    }

    // Score the guess
    const result = checkGuess(word, puzzle.word);
    const correct = word === puzzle.word;

    const created = await tx.guess.create({
      data: { puzzleDate: date, player, word, result, correct },
    });

    return { ...created, attemptNumber: playerGuesses.length + 1 };
  });

  return res.status(201).json({
    player: guess.player,
    word: guess.word,
    result: guess.result,
    correct: guess.correct,
    attemptNumber: guess.attemptNumber,
  });
}

import prisma from '../db.js';
import { isValidWord } from '../words.js';
import { resolveDate, getOrCreatePuzzle } from './puzzle_controller.js';
